library(readr)

# Check what's in the current directory using base R
cat('Current directory contents:\n')
list.files('.', recursive = TRUE)

cat('\n\nChecking if data/input exists:\n')
cat('data/input exists:', dir.exists('data/input'), '\n')

if (dir.exists('data/input')) {
  cat('\nContents of data/input:\n')
  list.files('data/input', recursive = TRUE)
} else {
  cat('data/input does not exist\n')
}

cat('\n\nListing all .tab files in the workspace:\n')
tab_files <- list.files('.', pattern = '\\.tab$', recursive = TRUE, full.names = TRUE)
for (f in tab_files) {
  cat(f, '\n')
}

